function bindStrokes(root, sw) {
  const stack = [root];
  while (stack.length) {
    const n = stack.pop();
    if ('constraints' in n) n.constraints = { horizontal: 'SCALE', vertical: 'SCALE' };
    if (['VECTOR','BOOLEAN_OPERATION','ELLIPSE','LINE'].includes(n.type)) {
      const hasStroke = n.strokes?.length > 0;
